import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"Create your first project","description":"","frontmatter":{"title":"Create your first project"},"headers":[],"relativePath":"docs/getting-started/create-first-project.md","filePath":"docs/getting-started/create-first-project.md","lastUpdated":1790394058000}'),s={name:"docs/getting-started/create-first-project.md"};function i(n,e,c,d,p,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="create-your-first-project" tabindex="-1">Create your first project <a class="header-anchor" href="#create-your-first-project" aria-label="Permalink to &quot;Create your first project&quot;">​</a></h1><p>Everything in OrbySystems happens inside a <strong>project</strong> — a private, self-contained space that holds one focused set of data, along with the categories, rules, and chat history that go with it. See <a href="/docs/concepts/projects">Projects</a> for the concept in more depth; this page just walks through creating one.</p><h2 id="pick-a-kind-of-project" tabindex="-1">Pick a kind of project <a class="header-anchor" href="#pick-a-kind-of-project" aria-label="Permalink to &quot;Pick a kind of project&quot;">​</a></h2><p>Click <strong>New Project</strong> and give it a name, then choose what kind of project it is:</p><ul><li><strong>Income/Spending</strong> — everyday bank and credit card activity.</li><li><strong>Investment</strong> — brokerage accounts, holdings, and performance.</li><li><strong>Fixed Assets</strong> — manually tracked assets and liabilities (a house, a car, loans).</li><li><strong>General Documents</strong> — just chat over documents, with no ready-made analyses.</li><li><strong>Combined Finance</strong> — combines other finance projects together for a net-worth or retirement view across all of them.</li></ul><p>Each option shows a one-line description to help you decide. If you&#39;re not sure yet, Income/Spending is the most common starting point.</p><h2 id="try-it-with-demo-data" tabindex="-1">Try it with demo data <a class="header-anchor" href="#try-it-with-demo-data" aria-label="Permalink to &quot;Try it with demo data&quot;">​</a></h2><p>For every kind except Fixed Assets, General Documents, and Combined Finance, the dialog offers a <strong>use demo data</strong> toggle. Turning it on seeds the new project with realistic sample transactions, so you can immediately try <a href="/docs/getting-started/browse-recipes">Recipes</a> and <a href="/docs/getting-started/ask-questions">ask questions</a> before importing anything real.</p><p>Once you save, OrbySystems creates the project and switches to it right away — no separate storage-location step to think about.</p><h2 id="next-step" tabindex="-1">Next step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next step&quot;">​</a></h2><p>With a project created, the next step is giving it real data: <a href="/docs/getting-started/add-first-source">Add your first source</a>.</p>',11)])])}const u=t(s,[["render",i]]);export{g as __pageData,u as default};
